@dataclass(frozen=True)
class HexCoord:
    """
    Axial coordinates (q, r) for hex grid.
    s = -q - r (implicit).
    """
    q: int
    r: int


@dataclass(frozen=True)
class VelocityState:
    """
    Velocity vector at a node, including magnitude and direction.
    direction is an integer encoding from 0-5; None at the start node by convention.
    """
    magnitude: float      # speed
    direction: int        # heading angle ordinal


@dataclass
class Node:
    """
    Search node for H* on a hex grid.
    """
    location: HexCoord
    velocity: VelocityState
    parent: Optional["Node"] = None

    step_distance: Optional[float] = None  # The distance traveled from parent

    # Costs (optional, can be maintained externally)
    g_cost: float = 0.0  # actual travel time accumulated
    h_cost: float = 0.0  # heuristic travel time
    f_cost: float = 0.0  # total estimated cost


# ------------------------------
# Problem / environment model
# ------------------------------



DIRECTIONS: Tuple[Tuple[int, int], ...] = (
    ( 1,  0),  # 0: E
    ( 1, -1),  # 1: SE
    ( 0, -1),  # 2: SW
    (-1,  0),  # 3: W
    (-1,  1),  # 4: NW
    ( 0,  1),  # 5: NE
)




class HexGrid:
    """
    Hexagonal grid environment using axial coordinates.
    Responsible for neighbor generation and obstacle queries.
    """

    def __init__(
        self,
        hex_size: float,
        obstacles: Optional[Dict[HexCoord, bool]] = None,
        allowed: Optional[Set[HexCoord]] = None,  
    ) -> None:
        self.hex_size = hex_size
        self.obstacles = obstacles or {}
        self.allowed = allowed  # None => unbounded

    def is_blocked(self, coord: HexCoord) -> bool:
        """Return True if the cell is blocked or out of bounds (if bounds exist)."""
        #if self.allowed is not None and coord not in self.allowed:
        #    return True
        return coord in self.obstacles



    def neighbors(self, coord: HexCoord) -> List[HexCoord]:
        """
        Return the six adjacent axial coordinates (filtering out blocked ones).

        Uses pointy-top axial directions:
            (+1,  0), (+1, -1), (0, -1),
            (-1,  0), (-1, +1), (0, +1)

        Any neighbor for which `is_blocked(nei)` returns True will be excluded.
        """


        q0, r0 = coord.q, coord.r
        result: List[HexCoord] = []
        for dq, dr in DIRECTIONS:
            nei = HexCoord(q0 + dq, r0 + dr)
            if not self.is_blocked(nei):
                result.append(nei)
        return result


def cube_round(xf: float, yf: float, zf: float) -> Tuple[int, int, int]:
    """Round fractional cube coords to integer cube coords with x+y+z=0 constraint."""
    rx, ry, rz = round(xf), round(yf), round(zf)

    x_diff = abs(rx - xf)
    y_diff = abs(ry - yf)
    z_diff = abs(rz - zf)

    if x_diff > y_diff and x_diff > z_diff:
        rx = -ry - rz
    elif y_diff > z_diff:
        ry = -rx - rz
    else:
        rz = -rx - ry

    return int(rx), int(ry), int(rz)

def cube_to_axial(x: int, y: int, z: int) -> HexCoord:
    """Cube -> axial (q=x, r=z)."""
    return HexCoord(x, z)

def hex_line_one_side(a: HexCoord, b: HexCoord, *, eps: float) -> List[HexCoord]:
    """
    Standard hex line draw (ordered), but with a tiny epsilon nudge to force a consistent
    tie-break side on boundaries.
    """
    ax, ay, az = axial_to_cube(a)  # uses your existing function
    bx, by, bz = axial_to_cube(b)

    n = max(abs(ax - bx), abs(ay - by), abs(az - bz))
    if n == 0:
        return [a]

    out: List[HexCoord] = []
    for i in range(n + 1):
        t = i / n
        xf = ax + (bx - ax) * t
        yf = ay + (by - ay) * t
        zf = az + (bz - az) * t

        # Nudge while preserving x+y+z=0.
        # Two parities are generated by eps=+1e-6 and eps=-1e-6.
        xf += eps
        yf += eps
        zf -= 2.0 * eps

        rx, ry, rz = cube_round(xf, yf, zf)
        out.append(cube_to_axial(rx, ry, rz))

    # De-dupe consecutive repeats (can happen due to rounding ties)
    deduped = [out[0]]
    for h in out[1:]:
        if h != deduped[-1]:
            deduped.append(h)

    return deduped

def hexes_in_between_solid(
    a: HexCoord,
    b: HexCoord,
    *,
    include_endpoints: bool = False,
    eps: float = 1e-6,
) -> Set[HexCoord]:
    """
    "Solid" (supercover-ish) set of hexes between a and b:
    union of left-parity and right-parity line draws.

    - include_endpoints=False excludes a and b
    """
    line_l = hex_line_one_side(a, b, eps=+eps)
    line_r = hex_line_one_side(a, b, eps=-eps)

    s = set(line_l) | set(line_r)

    if not include_endpoints:
        s.discard(a)
        s.discard(b)
    return s
def get_available_nodes_in_dir(
    start: HexCoord,
    direction: int,
    obs: Union[Set[HexCoord], Iterable[HexCoord], Dict[HexCoord, bool]],
    obs_radius: int,
    include_start: bool = True,
    ray_range: Optional[int] = None,   # <-- NEW: cap number of returned nodes
) -> Set[HexCoord]:
    """
    Return a set of nodes along a ray starting at `start` stepping in `direction`
    until the next node would be within `obs_radius` (hex steps) of any obstacle.

    If `ray_range` is not None, return at most that many nodes (still stopping
    early if an unsafe node is encountered).

    - direction: 0..5 using the global DIRECTIONS
    - obs: set/iterable of HexCoord, or dict[HexCoord, bool] (like your obstacle maps)
    - obs_radius: non-negative integer. 0 means "stop when you hit an obstacle cell".
    - include_start: if False, `start` is not included (even if safe).
    - ray_range: optional non-negative integer cap on number of nodes returned.
        * ray_range = 0 -> returns empty set
        * include_start=True, ray_range=1 -> may return {start} if safe
        * include_start=False, ray_range=1 -> may return {start + step} if safe
        * ray_range=None -> preserves current behavior (unbounded except MAX_STEPS)
    """
    if obs_radius < 0:
        raise ValueError("obs_radius must be a non-negative integer")

    if ray_range is not None:
        if not isinstance(ray_range, int):
            raise TypeError("ray_range must be an int or None")
        if ray_range < 0:
            raise ValueError("ray_range must be a non-negative integer")

    # Normalize obs to a set of HexCoord (supports dict obstacle maps)
    if isinstance(obs, dict):
        obs_set: Set[HexCoord] = set(obs.keys())
    else:
        obs_set = set(obs)

    # If there are no obstacles and ray_range is None, the ray is unbounded; we must cap it.
    MAX_STEPS = 10000

    # Precompute a "danger zone" if it’s cheaper than checking all obstacles each step.
    use_precompute = (obs_radius > 0 and len(obs_set) * (obs_radius ** 2) < 200000)

    if use_precompute:
        danger: Set[HexCoord] = set()
        for o in obs_set:
            danger |= hex_disk(o, obs_radius)   # already defined in your file

        def is_safe(c: HexCoord) -> bool:
            return c not in danger
    else:
        def is_safe(c: HexCoord) -> bool:
            for o in obs_set:
                if hdist(c, o) <= obs_radius:
                    return False
            return True

    # Walk the ray
    out: Set[HexCoord] = set()
    step = DIRECTIONS[direction % 6]

    # If excluding start, begin from the first step away from start.
    curr = start if include_start else add_coords(start, step)

    # Determine how many nodes to attempt to collect.
    # - If ray_range is None: preserve existing behavior (cap by MAX_STEPS).
    # - If ray_range is provided: attempt exactly that many (or stop early if unsafe).
    if ray_range is None:
        limit = MAX_STEPS + 1
    else:
        limit = ray_range

    for _ in range(limit):
        if not is_safe(curr):
            break
        out.add(curr)
        curr = add_coords(curr, step)

    return out

